-- -----------------------------------------------------
-- procedure insert_loop
-- -----------------------------------------------------

DELIMITER $$
USE `dapdap`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `insert_loop`()
BEGIN
    DECLARE i INT DEFAULT 1;
    WHILE i <= 100 DO
        INSERT INTO board_posts 
            (created_at, updated_at, content, image_url, likes, title, views, author_id)
        VALUES 
            (NOW(), NOW(), CONCAT('테스트 내용 ', i), NULL, 0, CONCAT('테스트 제목 ', i), 0, 1);
        SET i = i + 1;
    END WHILE;
END$$

DELIMITER ;

-- -----------------------------------------------------
-- procedure insert_loop_500
-- -----------------------------------------------------

DELIMITER $$
USE `dapdap`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `insert_loop_500`()
BEGIN
    -- 101번부터 시작하도록 설정
    DECLARE i INT DEFAULT 101; 
    
    -- 500번까지 반복
    WHILE i <= 500 DO
        INSERT INTO board_posts 
            (created_at, updated_at, content, image_url, likes, title, views, author_id)
        VALUES 
            (NOW(), NOW(), CONCAT('테스트 내용 ', i), NULL, 0, CONCAT('테스트 제목 ', i), 0, 1);
        SET i = i + 1;
    END WHILE;
END$$

DELIMITER ;

